sys_script.script:
(function executeRule(current, previous) {
    // Auto-execute bootstrap for the x_casemgmt post-import remediation.
    //
    // SHIPPED INACTIVE. This rule fires correctly and still cannot complete the
    // remediation, so activating it is not the supported path. Read the record's
    // description, or docs/PDI_LIMITATIONS_AND_KNOWN_ISSUES.md section 9.4, before
    // relying on it.
    //
    // What it does: Fix Scripts do not auto-run when an Update Set is committed -
    // the platform only runs them on application install from a repository or the
    // Store. The commit engine applies every captured payload and then flips the
    // retrieved Update Set's state to 'committed', which fires this rule, which
    // resolves the Fix Script by name and dispatches it.
    //
    // Why that is not enough (measured on the target PDI, not inferred):
    //   - The commit engine REWRITES every committed record's sys_scope to the
    //     Update Set's application. This rule is declared global and is read back
    //     app-scoped after commit, as is the Fix Script it dispatches. The
    //     remediation then runs in the x_casemgmt scope, where
    //     GlideTableDescriptor and GlideSecurityManager both raise
    //     "... is not allowed in scoped applications".
    //   - Observed result: 'BOOTSTRAP|fired|...|scope=x_casemgmt' followed by
    //     'SUMMARY|verified=false|tables_built=0|acl_links_created=0|errors=121',
    //     all 121 errors being those two SecurityExceptions. Nothing was created.
    //   - No packaging change fixes it: the rewrite happens at commit time
    //     regardless of the scope the package declares.
    //   - The route that works is the global background script - see the operator
    //     messages below, which point there rather than at the Fix Script UI.
    //
    // Design notes that DID hold up, and are worth keeping:
    //   - when = after, i.e. synchronous and exactly once. An async variant was
    //     built and tested first, because giving the physical DDL its own
    //     transaction is attractive; it was rejected on evidence. For a single
    //     qualifying state transition the platform dispatched the async rule
    //     TWICE, milliseconds apart, and two concurrent passes would race on the
    //     destructive half of the table rebuild (one pass deleting the metadata
    //     the other had just created). The synchronous rule fires exactly once.
    //   - The dispatch below is wrapped in try/catch, so a failure inside the
    //     remediation can never abort the commit transaction. That property was
    //     exercised for real: the 121 errors were logged and the commit completed.
    //   - The condition is current.state.changesTo('committed') - the state
    //     TRANSITION, not merely the current value, because the platform writes
    //     to an already-committed retrieved Update Set more than once and each
    //     write would otherwise re-run the whole remediation.
    //   - The remediation body lives in exactly one place - the Fix Script named
    //     below, whose script field is
    //     servicenow-case-management-poc/scripts/post_import_remediation.js
    //     verbatim. It is resolved by name; no sys_id is hard-coded.
    //
    // Verification signal: every line the remediation emits is a gs.info()
    // prefixed 'X_CASEMGMT_REMEDIATION|'. The last one starts with
    // 'X_CASEMGMT_REMEDIATION|SUMMARY|' and carries verified=true|false. Read it
    // rather than assuming the dispatch succeeded.

    // sys_script_fix.name is max_length 40 on this release and the platform
    // truncates silently, so this literal must stay at 40 characters or fewer or
    // the lookup below will never match.
    var MARKER = 'X_CASEMGMT_REMEDIATION';
    var FIX_SCRIPT_NAME = 'x_casemgmt Post-Import Remediation';

    try {
        var fix = new GlideRecord('sys_script_fix');
        fix.addQuery('name', FIX_SCRIPT_NAME);
        fix.setLimit(1);
        fix.query();
        if (!fix.next()) {
            gs.warn(MARKER + '|BOOTSTRAP|Fix Script "' + FIX_SCRIPT_NAME +
                '" is not present on this instance. Run the remediation the way that works: paste' +
                ' servicenow-case-management-poc/scripts/post_import_remediation.js into' +
                ' System Definition > Scripts - Background with "In scope" = Global and run it' +
                ' (docs/HUMAN_DEPLOYMENT_RECREATE_GUIDE.md section 5).');
            return;
        }

        // gs.getCurrentScopeName() is logged deliberately: on the supported path it
        // reads 'x_casemgmt' rather than 'rhino.global', which is the single fact
        // that explains the 121 SecurityExceptions that follow.
        gs.info(MARKER + '|BOOTSTRAP|fired|remote_update_set=' + current.getValue('name') +
            '|state=' + current.getValue('state') + '|scope=' + gs.getCurrentScopeName() +
            '|dispatching Fix Script "' + FIX_SCRIPT_NAME + '"');

        new GlideScopedEvaluator().evaluateScript(fix, 'script', null);

        gs.info(MARKER + '|BOOTSTRAP|dispatch complete for "' + FIX_SCRIPT_NAME + '"');
    } catch (e) {
        gs.warn(MARKER + '|BOOTSTRAP|dispatch failed: ' + e +
            ' - do NOT retry through the Fix Script UI: the commit engine rewrites the installed' +
            ' Fix Script into the application scope, where GlideTableDescriptor and' +
            ' GlideSecurityManager are refused. Paste' +
            ' servicenow-case-management-poc/scripts/post_import_remediation.js into' +
            ' System Definition > Scripts - Background with "In scope" = Global and run it there' +
            ' (docs/HUMAN_DEPLOYMENT_RECREATE_GUIDE.md section 5).');
    }
})(current, previous);
